1	import * as THREE from 'three';
2	import { scene } from '../../core/renderer';
3	import { MAT } from '../../core/materials';
4	
5	/* [clearance] Dọn nhà, cây, cột đèn ngẫu nhiên đè lên công trình mới mà KHÔNG đụng tới chuỗi rand() của khu phố:
6	   sau khi cảnh đã dựng, gán ma trận scale 0 cho instance bị đè (cả level near lẫn far của LOD nhà), giống corridor.ts của hầm. */
7	export interface Rect { x0: number; x1: number; z0: number; z1: number }
8	export interface Building { mesh: THREE.InstancedMesh; i: number; x: number; z: number; w: number; d: number; h: number }
9	
10	const plants = () => new Set<THREE.Material>([MAT.trunk, MAT.leaf, MAT.palm, MAT.lampPole, MAT.bulb]);
11	const _m = new THREE.Matrix4(), _p = new THREE.Vector3(), _q = new THREE.Quaternion(), _s = new THREE.Vector3(), _zero = new THREE.Matrix4().makeScale(0, 0, 0);
12	
13	/* Các InstancedMesh nhà (con của THREE.LOD do buildCity dựng); level 0 là bản gần có cửa sổ */
14	function buildingMeshes() {
15	  const out: { mesh: THREE.InstancedMesh; near: boolean }[] = [];
16	  scene.traverse((o) => {
17	    const m = o as THREE.InstancedMesh;
18	    if (m.isInstancedMesh && m.parent && (m.parent as THREE.LOD).isLOD) out.push({ mesh: m, near: (m.parent as THREE.LOD).levels[0]?.object === m });
19	  });
20	  return out;
21	}
22	/* Nhà đang hiện (scale > 0) ở level near, tọa độ thế giới */
23	export function collectBuildings(): Building[] {
24	  scene.updateMatrixWorld(true);
25	  const list: Building[] = [];
26	  for (const { mesh, near } of buildingMeshes()) {
27	    if (!near) continue;
28	    for (let i = 0; i < mesh.count; i++) {
29	      mesh.getMatrixAt(i, _m); _m.decompose(_p, _q, _s);
30	      if (_s.x < 1e-6) continue;
31	      _p.applyMatrix4(mesh.matrixWorld);
32	      list.push({ mesh, i, x: _p.x, z: _p.z, w: _s.x, d: _s.z, h: _s.y });
33	    }
34	  }
35	  return list;
36	}
37	/* Ảnh chụp ma trận nhà ngay trước khi dọn, để kiểm tra "nhà không bị dọn giữ nguyên ma trận" */
38	export const snapshot = new Map<THREE.InstancedMesh, Float32Array>();
39	
40	export function clearRects(rects: Rect[], margin: number) {
41	  scene.updateMatrixWorld(true);
42	  const pl = plants(); let nb = 0, np = 0;
43	  const hit = (x: number, z: number, hw: number, hd: number) => rects.some((r) => x + hw > r.x0 - margin && x - hw < r.x1 + margin && z + hd > r.z0 - margin && z - hd < r.z1 + margin);
44	  scene.traverse((obj) => {
45	    const o = obj as THREE.InstancedMesh;
46	    if (!o.isInstancedMesh) return;
47	    const building = !!o.parent && (o.parent as THREE.LOD).isLOD;
48	    if (!building && !pl.has(o.material as THREE.Material)) return;
49	    if (building && !snapshot.has(o)) snapshot.set(o, (o.instanceMatrix.array as Float32Array).slice());
50	    let changed = false;
51	    for (let i = 0; i < o.count; i++) {
52	      o.getMatrixAt(i, _m); _m.decompose(_p, _q, _s);
53	      if (_s.x < 1e-6) continue;
54	      _p.applyMatrix4(o.matrixWorld);
55	      if (hit(_p.x, _p.z, building ? _s.x / 2 : 1.5, building ? _s.z / 2 : 1.5)) { o.setMatrixAt(i, _zero); changed = true; building ? nb++ : np++; }
56	    }
57	    if (changed) o.instanceMatrix.needsUpdate = true;
58	  });
59	  return { buildings: nb, plants: np };
60	}
