1	/* ===== Worker + Durable Object phòng bầu trời chung: bọc SkyRoom, WebSocket hibernation ===== */
2	import { multiParams as P } from '../../../src/explore/multi/params';
3	import { SkyRoom } from './room';
4	import type { Out } from './room';
5	
6	interface Env { SKY: DurableObjectNamespace; ALLOWED_ORIGINS: string }
7	interface Att { id: string; slot: number; name: string; seen?: number }   // seen: giờ có tin cuối của người giữ slot, ghi thưa (mỗi heartbeatMs) để sống sót qua hibernation
8	
9	// So khớp scheme + hostname, bỏ cổng
10	function originKey(o: string): string | null {
11	  try { const u = new URL(o); return u.protocol + '//' + u.hostname; } catch { return null; }
12	}
13	
14	// Mục cho phép có '*' (vd. bản xem trước PR của Netlify): '*' chỉ khớp một đoạn chữ thường/số, không có '.' hay '-'
15	function originAllowed(key: string, pattern: string): boolean {
16	  const p = originKey(pattern.replace(/\*/g, 'x'));
17	  if (!p) return false;
18	  if (!pattern.includes('*')) return p === key;
19	  const re = new RegExp('^' + pattern.trim().split('*').map(s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('[a-z0-9]+') + '$');
20	  return re.test(key);
21	}
22	
23	export default {
24	  async fetch(req: Request, env: Env): Promise<Response> {
25	    const url = new URL(req.url);
26	    if (url.pathname !== '/sky') return new Response('Not found', { status: 404 });
27	    if (req.headers.get('Upgrade') !== 'websocket') return new Response('Expected WebSocket', { status: 426 });
28	    const key = originKey(req.headers.get('Origin') || '');
29	    if (!key || !env.ALLOWED_ORIGINS.split(',').some(s => originAllowed(key, s.trim()))) return new Response('Forbidden', { status: 403 });
30	    return env.SKY.get(env.SKY.idFromName('sky')).fetch(req);
31	  }
32	};
33	
34	export class SkyObject implements DurableObject {
35	  private room = new SkyRoom();
36	  private names = new Map<number, string>();
37	  private armed: boolean | null = null;   // đã đặt alarm chưa; null = chưa biết (vừa dựng hoặc vừa thức dậy): hỏi storage một lần
38	
39	  constructor(private state: DurableObjectState, _env: Env) {
40	    // Đánh thức sau hibernation: dựng lại phòng từ attachment của từng socket
41	    const now = Date.now();
42	    const list: Att[] = [];
43	    for (const ws of this.state.getWebSockets()) {
44	      const a = ws.deserializeAttachment() as Att | null;
45	      if (!a) continue;
46	      this.room.connect(a.id, now);
47	      if (a.slot >= 0) list.push(a);
48	    }
49	    this.room.restore(list, now);
50	  }
51	
52	  async fetch(_req: Request): Promise<Response> {
53	    const pair = new WebSocketPair();
54	    const [client, server] = [pair[0], pair[1]];
55	    const id = crypto.randomUUID();
56	    this.state.acceptWebSocket(server);
57	    server.serializeAttachment({ id, slot: -1, name: '' } as Att);
58	    const outs = this.room.connect(id, Date.now());
59	    if (outs === null) { server.close(1013, 'full'); return new Response(null, { status: 503 }); }
60	    this.dispatch(outs);
61	    return new Response(null, { status: 101, webSocket: client });
62	  }
63	
64	  async webSocketMessage(ws: WebSocket, data: string | ArrayBuffer): Promise<void> {
65	    const a = ws.deserializeAttachment() as Att | null;
66	    if (!a || typeof data !== 'string') return;
67	    this.dispatch(this.room.message(a.id, data, Date.now()));
68	    await this.armAlarm();
69	  }
70	
71	  async webSocketClose(ws: WebSocket): Promise<void> { this.drop(ws); }
72	  async webSocketError(ws: WebSocket): Promise<void> { this.drop(ws); }
73	
74	  async alarm(): Promise<void> {
75	    this.armed = false;   // alarm đã chạy thì không còn alarm nào chờ
76	    this.dispatch(this.room.sweep(Date.now()));
77	    await this.armAlarm();
78	  }
79	
80	  private drop(ws: WebSocket): void {
81	    const a = ws.deserializeAttachment() as Att | null;
82	    if (a) this.dispatch(this.room.disconnect(a.id));
83	  }
84	
85	  // Gửi tin ra socket rồi ghi lại slot/tên/seen mới vào attachment (để sống sót qua hibernation); seen chỉ ghi khi cũ hơn heartbeatMs
86	  private dispatch(outs: Out[]): void {
87	    const socks = this.state.getWebSockets();
88	    for (const o of outs) {
89	      const text = JSON.stringify(o.msg);
90	      for (const ws of socks) {
91	        const a = ws.deserializeAttachment() as Att | null;
92	        if (!a || (o.to !== 'all' && o.to !== a.id)) continue;
93	        try { ws.send(text); } catch { /* socket đã đóng */ }
94	      }
95	      if (o.msg.t === 'lobby') this.names = new Map(o.msg.flyers.map(f => [f.slot, f.name]));
96	    }
97	    for (const ws of socks) {
98	      const a = ws.deserializeAttachment() as Att | null;
99	      if (!a) continue;
100	      const slot = this.room.slotOf(a.id);
101	      const name = slot >= 0 ? (this.names.get(slot) ?? a.name) : '';
102	      const seen = this.room.seenOf(a.id);
103	      const stale = slot >= 0 && !(seen - (a.seen ?? -Infinity) < P.heartbeatMs);
104	      if (slot !== a.slot || name !== a.name || stale) ws.serializeAttachment(slot >= 0 ? { id: a.id, slot, name, seen } : { id: a.id, slot, name } as Att);
105	    }
106	  }
