108	  private async armAlarm(): Promise<void> {
109	    if (!this.room.hasFlyers() || this.armed) return;
110	    if (this.armed === null && (await this.state.storage.getAlarm()) !== null) { this.armed = true; return; }
111	    this.armed = true;
112	    try { await this.state.storage.setAlarm(Date.now() + P.sweepMs); } catch (e) { this.armed = false; throw e; }
113	  }
