1	/* ===== Dù lượn nhiều người: máy trạng thái phiên (không DOM, không three) ===== */
2	import type { Flyer, ServerMsg } from './protocol';
3	import type { Transport } from './client';
4	import { multiParams } from './params';
5	
6	export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
7	export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';
8	
9	export class MultiSession {
10	  phase: Phase = 'connecting';
11	  flyers: Flyer[] = [];
12	  mySlot = -1;
13	  watched = -1;       // slot đang xem, -1 = không ai
14	  invite = false;     // đang xem và còn chỗ trống
15	  notice: Notice = '';
16	  name = '';
17	  onChange: () => void = () => {};
18	  onPos: (f: number[][]) => void = () => {};
19	  private t: Transport | null = null;
20	  private disposed = false;
21	  private first = true; // chưa nhận lobby nào
22	
23	  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n)) {}
24	
25	  open(): void {
26	    this.connect().then(t => {
27	      if (this.disposed) { t.close(); return; }
28	      this.t = t;
29	      t.onMessage = m => this.recv(m);
30	      t.onClose = () => this.lost();
31	    }, () => {
32	      if (this.disposed) return;
33	      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
34	    });
35	  }
36	
37	  join(name: string): void {
38	    this.name = name; this.notice = '';
39	    this.t?.send({ t: 'join', name });
40	  }
41	
42	  // Rời chỗ bay (do rời máy): trả slot, chuyển sang xem, báo 'released' như khi máy chủ thu hồi chỗ
43	  leave(): void {
44	    if (this.phase !== 'flying') return;
45	    this.t?.send({ t: 'leave' });
46	    this.notice = 'released'; this.toWatching();
47	    this.onChange();
48	  }
49	
50	  // ts: giờ gửi (ms, đồng hồ của khách này) để người xem đặt mẫu theo trục giờ người gửi
51	  sendPos(x: number, y: number, z: number, yaw: number, bank: number, ts: number): void {
52	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank, ts });
53	  }
54	
55	  heartbeat(): void {
56	    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
57	  }
58	
59	  dispose(): void {
60	    this.disposed = true;
61	    this.t?.close(); this.t = null;
62	  }
63	
64	  private toWatching(): void {
65	    this.phase = 'watching'; this.mySlot = -1;
66	    this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
67	    this.fixWatched();
68	  }
69	  private mySlotWas = -1;
70	
71	  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác
72	  private fixWatched(): void {
73	    const ids = this.flyers.map(f => f.slot);
74	    if (this.phase === 'watching') {
75	      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
76	      this.invite = ids.length < multiParams.slots;
77	    } else { this.watched = -1; this.invite = false; }
78	  }
79	
80	  private lost(): void {
81	    if (this.disposed) return;
82	    this.phase = 'solo'; this.notice = 'lost';
83	    this.flyers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
84	    this.t = null; this.onChange();
85	  }
86	
87	  private recv(m: ServerMsg): void {
88	    if (this.disposed) return;
89	    switch (m.t) {
90	      case 'lobby':
91	        this.flyers = m.flyers;
92	        if (this.first) {
93	          this.first = false;
94	          if (m.flyers.length >= multiParams.slots) this.phase = 'watching';
95	          else this.phase = 'lobby';
96	        }
97	        // đang bay: danh sách chỉ để hiển thị
98	        this.fixWatched();
99	        break;
100	      case 'joined':
101	        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
102	        this.fixWatched();
103	        break;
104	      case 'rejected':
105	        if (m.why === 'name') this.notice = 'nameBad';
106	        else {
107	          this.notice = 'late';   // giành trước khi đang xem, hoặc ngay ở sảnh (chỗ cuối vừa có người lúc bấm): đều báo lý do
108	          this.phase = 'watching';
109	          this.fixWatched();
110	        }
111	        break;
112	      case 'pos':
113	        this.onPos(m.f);
114	        return;
115	      case 'released':
116	        if (this.phase === 'flying') { this.notice = 'released'; this.toWatching(); }
117	        break;
118	    }
119	    this.onChange();
120	  }
121	}
