11	
12	// f: mỗi phần tử [slot, x, y, z, yaw, bank, giờ gửi (ms)]; chỉ gồm slot có vị trí mới. Giờ gửi = ts của khách, khách cũ không gửi ts thì là giờ máy chủ nhận;
13	// mỗi slot một trục giờ riêng, khách nhận tự quy đổi. Máy chủ cũ (trước bản sửa giật) gửi 6 phần tử và phát lại vị trí cũ của mọi slot: khách mới nhận được cả hai dạng
14	export type ServerMsg =
15	  | { t: 'lobby'; flyers: Flyer[] }
16	  | { t: 'joined'; slot: number }
17	  | { t: 'rejected'; why: 'full' | 'name' }
18	  | { t: 'pos'; f: number[][] }
19	  | { t: 'released' };
20	
21	// Ký tự trông như khoảng trống dù thuộc nhóm chữ/ký hiệu (chữ đệm Hangul, chữ nổi trống, nguyên âm ẩn Khmer): không tính là chữ thấy được
22	const BLANK = /[\u115F\u1160\u3164\uFFA0\u2800\u17B4\u17B5]/gu;
23	const VISIBLE = /[\p{L}\p{N}\p{S}\p{P}]/u;
24	
25	/* Bỏ ký tự điều khiển và bidi/định dạng (giữ U+200D để ghép emoji), cắt khoảng trắng.
26	   null nếu: rỗng; không có chữ/số/ký hiệu/dấu câu nào thấy được; quá nameMax grapheme; một grapheme quá graphemeCpMax code point (chồng dấu); tổng quá nameCpMax code point */
27	export function exSanitizeName(raw: string): string | null {
28	  if (typeof raw !== 'string') return null;
29	  const s = raw.replace(/[\p{Cc}\p{Cf}]/gu, c => (c === '\u200D' ? c : '')).trim();
30	  if (!s || !VISIBLE.test(s.replace(BLANK, ''))) return null;
31	  const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
32	  let n = 0, cps = 0;
33	  for (const g of seg.segment(s)) {
34	    let k = 0;
35	    for (const _ of g.segment) k++;
36	    cps += k;
37	    if (++n > multiParams.nameMax || k > multiParams.graphemeCpMax || cps > multiParams.nameCpMax) return null;
38	  }
39	  return s;
40	}
